import { derive } from "../variable-tools/derive.js";
import constants from "../../data/state-rules.json" with { type: "json" };

const {
  eventOrder,
  weekdaysByUtcDay,
  routeValues,
  endingStageValues,
  errorMessages,
} = constants;

const monthLengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeapYear(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function actualDate(value) {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const parts = value.split("-").map(Number);
  const year = parts[0];
  const month = parts[1];
  const day = parts[2];
  if (year < 1 || month < 1 || month > 12) return null;
  const maximumDay = month === 2 && isLeapYear(year) ? 29 : monthLengths[month - 1];
  if (day < 1 || day > maximumDay) return null;
  let days = (year - 1) * 365 + Math.floor((year - 1) / 4) - Math.floor((year - 1) / 100) + Math.floor((year - 1) / 400) + day - 1;
  for (let index = 1; index < month; index += 1) days += index === 2 && isLeapYear(year) ? 29 : monthLengths[index - 1];
  return { days: days };
}

function issue(issues, path, code) {
  issues.push({ path: path, code: code, message: errorMessages[code] });
}

export function validate(context) {
  const before = context.before;
  const candidate = context.candidate;
  const facts = context.facts;
  const priorFacts = context.priorFacts;
  const floorBefore = context.floorBefore;
  const issues = [];
  const person = candidate?.林茜;
  const world = candidate?.世界;

  for (const [path, value, min, max, integer] of [
    ["/林茜/感情", person?.感情, 0, 999, false],
    ["/林茜/堕落", person?.堕落, 0, 999, false],
    ["/世界/小时", world?.小时, 0, 23, true],
    ["/世界/分钟", world?.分钟, 0, 59, true],
    ["/世界/状态_A1_计数", world?.状态_A1_计数, 0, 9, true],
  ]) {
    if (
      typeof value !== "number" ||
      !Number.isFinite(value) ||
      value < min ||
      value > max ||
      (integer && !Number.isInteger(value))
    ) {
      issue(issues, path, "NUMBER_INVALID");
    }
  }

  if (
    typeof person?.内心想法 !== "string" ||
    !/^\*\*[\s\S]+\*\*$/.test(person.内心想法)
  ) {
    issue(issues, "/林茜/内心想法", "INNER_THOUGHT_INVALID");
  }

  const options = candidate?.行动选项;
  if (
    !Array.isArray(options) ||
    options.length !== 4 ||
    options.some((value) => typeof value !== "string" || !value.trim())
  ) {
    issue(issues, "/行动选项", "OPTIONS_TUPLE_INVALID");
  } else {
    if (new Set(options.map((value) => value.trim())).size !== 4)
      issue(issues, "/行动选项", "OPTIONS_DUPLICATED");
    for (const index of [0, 3])
      if (!options[index].trim().startsWith("元指令:"))
        issue(issues, `/行动选项/${index}`, "OPTION_PREFIX_INVALID");
  }

  const date = actualDate(world?.日期);
  const a1Date = actualDate(world?.状态_A1_日期);
  const d001Date = actualDate(world?.事件_D001记录日期);
  if (!date) issue(issues, "/世界/日期", "DATE_INVALID");
  if (!a1Date) issue(issues, "/世界/状态_A1_日期", "DATE_INVALID");
  if (!d001Date) issue(issues, "/世界/事件_D001记录日期", "DATE_INVALID");
  if (date && world.星期 !== weekdaysByUtcDay[(date.days + 1) % 7])
    issue(issues, "/世界/星期", "WEEKDAY_MISMATCH");
  if (typeof world?.地点 !== "string" || !world.地点.trim())
    issue(issues, "/世界/地点", "LOCATION_MISSING");

  let foundGap = false;
  for (const event of eventOrder) {
    const value = world?.已触发事件?.[event];
    if (value !== true && value !== false)
      issue(issues, `/世界/已触发事件/${event}`, "EVENT_FLAG_INVALID");
    if (value === false) foundGap = true;
    else if (value === true && foundGap)
      issue(issues, `/世界/已触发事件/${event}`, "EVENT_ORDER_INVALID");
  }

  if (before?.世界?.已离婚 === true && world?.已离婚 !== true)
    issue(issues, "/世界/已离婚", "DIVORCE_REVERTED");
  if (
    before?.世界?.终局阶段 !== endingStageValues[0] &&
    world?.终局阶段 === endingStageValues[0]
  )
    issue(issues, "/世界/终局阶段", "ENDING_STAGE_REVERTED");
  if (
    before?.世界?.终局路线 !== routeValues.unassigned &&
    world?.终局路线 !== before.世界.终局路线 &&
    facts?.ending?.explicitReselection !== true
  ) {
    issue(issues, "/世界/终局路线", "ENDING_ROUTE_LOCKED");
  }

  const expected = derive({
    before: before,
    candidate: candidate,
    facts: facts,
    priorFacts: priorFacts,
    floorBefore: floorBefore,
  });
  for (const [path, actual, wanted] of [
    ["/林茜/感情", candidate?.林茜?.感情, expected?.林茜?.感情],
    ["/林茜/堕落", candidate?.林茜?.堕落, expected?.林茜?.堕落],
    ["/世界/日期", world?.日期, expected?.世界?.日期],
    ["/世界/时间", world?.时间, expected?.世界?.时间],
    ["/世界/已触发事件", world?.已触发事件, expected?.世界?.已触发事件],
    ["/世界/终局路线", world?.终局路线, expected?.世界?.终局路线],
    ["/世界/终局阶段", world?.终局阶段, expected?.世界?.终局阶段],
  ]) {
    if (JSON.stringify(actual) !== JSON.stringify(wanted))
      issue(issues, path, "DERIVED_VALUE_MISMATCH");
  }
  return { issues: issues };
}

import constants from "../../data/state-rules.json" with { type: "json" };

const {
  eventOrder,
  weekdaysByUtcDay,
  periodByHour,
  routeValues,
  relationship,
  corruption,
} = constants;

function clone(value) {
  if (Array.isArray(value)) return value.map((item) => clone(item));
  if (value !== null && typeof value === "object") {
    const result = {};
    for (const key of Object.keys(value)) result[key] = clone(value[key]);
    return result;
  }
  return value;
}

function hasOwn(object, key) {
  return (
    object !== null && typeof object === "object" && Object.hasOwn(object, key)
  );
}

function coerceFinite(object, key, minimum, maximum, integer = false) {
  if (!hasOwn(object, key)) return;
  const value = Number(object[key]);
  if (!Number.isFinite(value) || (integer && !Number.isInteger(value))) return;
  object[key] = Math.min(maximum, Math.max(minimum, value));
}

const monthLengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeapYear(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function daysBeforeYear(year) {
  const previous = year - 1;
  return previous * 365 + Math.floor(previous / 4) - Math.floor(previous / 100) + Math.floor(previous / 400);
}

function daysInMonth(year, month) {
  return month === 2 && isLeapYear(year) ? 29 : monthLengths[month - 1];
}

function parseDate(date, hour, minute) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(date))) return null;
  if (!Number.isInteger(hour) || !Number.isInteger(minute) || hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;
  const parts = String(date).split("-").map(Number);
  const year = parts[0];
  const month = parts[1];
  const day = parts[2];
  if (year < 1 || month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) return null;
  let days = daysBeforeYear(year) + day - 1;
  for (let index = 1; index < month; index += 1) days += daysInMonth(year, index);
  return { year: year, month: month, day: day, hour: hour, minute: minute, days: days };
}

function dateFromDayIndex(days) {
  if (!Number.isInteger(days) || days < 0 || days >= daysBeforeYear(10000)) return null;
  let low = 1;
  let high = 10000;
  while (low + 1 < high) {
    const middle = Math.floor((low + high) / 2);
    if (daysBeforeYear(middle) <= days) low = middle;
    else high = middle;
  }
  let remaining = days - daysBeforeYear(low);
  let month = 1;
  while (remaining >= daysInMonth(low, month)) {
    remaining -= daysInMonth(low, month);
    month += 1;
  }
  const date = String(low).padStart(4, "0") + "-" + String(month).padStart(2, "0") + "-" + String(remaining + 1).padStart(2, "0");
  return { date: date, year: low, month: month, day: remaining + 1 };
}

function periodFor(hour) {
  return periodByHour[hour];
}

function deriveClock(before, result, facts) {
  const world = before?.世界;
  const candidateWorld = result?.世界;
  if (!world || !candidateWorld) return;
  const start = parseDate(world.日期, world.小时, world.分钟);
  const elapsed = facts?.elapsedMinutes;
  if (!start || !Number.isInteger(elapsed) || elapsed < 0) return;
  const endMinutes = start.days * 1440 + start.hour * 60 + start.minute + elapsed;
  const endDays = Math.floor(endMinutes / 1440);
  const end = dateFromDayIndex(endDays);
  if (!end) return;
  const minuteOfDay = endMinutes - endDays * 1440;
  candidateWorld.日期 = end.date;
  candidateWorld.星期 = weekdaysByUtcDay[(endDays + 1) % 7];
  candidateWorld.小时 = Math.floor(minuteOfDay / 60);
  candidateWorld.分钟 = minuteOfDay % 60;
  candidateWorld.时间 = periodFor(candidateWorld.小时);
}

function deriveA1(before, result, facts) {
  const previous = before?.世界;
  const world = result?.世界;
  if (!previous || !world) return;
  const priorDateValid = parseDate(previous.状态_A1_日期, 0, 0);
  const endDateValid = parseDate(world.日期, 0, 0);
  const priorCountValid =
    Number.isInteger(previous.状态_A1_计数) &&
    previous.状态_A1_计数 >= 0 &&
    previous.状态_A1_计数 <= 9;
  if (!priorDateValid || !endDateValid || !priorCountValid) return;
  const crossedDate = previous.状态_A1_日期 !== world.日期;
  const completions = Array.isArray(facts?.completedA1Events)
    ? facts.completedA1Events.filter(
        (event) =>
          (event?.kind === "D002" || event?.kind === "D003") &&
          event.completedDate === world.日期,
      ).length
    : 0;
  world.状态_A1_日期 = crossedDate ? world.日期 : previous.状态_A1_日期;
  world.状态_A1_计数 = Math.min(
    9,
    (crossedDate ? 0 : previous.状态_A1_计数) + completions,
  );
}

function deriveEvents(before, result, facts) {
  if (!before?.世界?.已触发事件 || !result?.世界) return;
  const events = clone(before.世界.已触发事件);
  const completed = new Set(
    Array.isArray(facts?.completedOneTimeEvents)
      ? facts.completedOneTimeEvents
      : [],
  );
  let blocked = false;
  for (const event of eventOrder) {
    if (events[event] === true) continue;
    if (!blocked && completed.has(event)) events[event] = true;
    else blocked = true;
  }
  result.世界.已触发事件 = events;
}

function relationshipTotals(factsList) {
  let positive = 0;
  let negative = false;
  let intimacy = 0;
  for (const facts of factsList) {
    const positiveDelta = facts?.relationship?.positiveDelta;
    const negativeDelta = facts?.relationship?.negativeDelta;
    if (Number.isInteger(positiveDelta) && positiveDelta > 0)
      positive += positiveDelta;
    if (negativeDelta === relationship.dailyMinimum) negative = true;
    intimacy = Math.max(
      intimacy,
      relationship.intimacyTiers[facts?.relationship?.intimacyTier] ?? 0,
    );
  }
  return {
    daily:
      Math.min(relationship.dailyPositiveMaximum, positive) -
      (negative ? Math.abs(relationship.dailyMinimum) : 0),
    intimacy: intimacy,
  };
}

function corruptionTotal(factsList) {
  const records = factsList.map((facts) => facts?.corruptionSettlement);
  let settlementIndex = -1;
  for (let index = 0; index < records.length; index += 1)
    if (records[index]?.settlementTriggered === true) settlementIndex = index;
  if (settlementIndex < 0) return 0;

  const settledRecords = records.slice(0, settlementIndex + 1).filter(Boolean);
  const occurrenceByTier = new Map();
  let outcome = 0;
  let anomaly = false;
  let specialClaimed = false;
  for (const value of settledRecords) {
    for (const behavior of value.behaviors ?? []) {
      if (
        behavior.tier in corruption.baseValues &&
        behavior.tier !== "none" &&
        Number.isInteger(behavior.count)
      ) {
        occurrenceByTier.set(
          behavior.tier,
          Math.min(
            3,
            (occurrenceByTier.get(behavior.tier) ?? 0) + behavior.count,
          ),
        );
      }
    }
    outcome = Math.max(outcome, corruption.resultValues[value.resultTier] ?? 0);
    anomaly ||= value.materialAnomaly === true;
    specialClaimed ||= value.specialStimulatorOnly === true;
  }

  const onlyStimulator = [...occurrenceByTier.keys()].every(
    (tier) => tier === "stimulator",
  );
  if (specialClaimed && occurrenceByTier.size > 0 && onlyStimulator) return 5;

  let highestBehavior = 0;
  for (const [tier, occurrences] of occurrenceByTier) {
    const base = corruption.baseValues[tier];
    const repetition = occurrences >= 3 ? 10 : occurrences === 2 ? 5 : 0;
    highestBehavior = Math.max(highestBehavior, base + repetition);
  }
  return Math.min(
    corruption.maximumDelta,
    highestBehavior + outcome + (anomaly ? 5 : 0),
  );
}

function deriveNumbers(before, result, facts, priorFacts, floorBefore) {
  if (!before?.林茜 || !result?.林茜) return;
  const floorAffection = Number(floorBefore?.林茜?.感情 ?? before.林茜.感情);
  const floorCorruption = Number(floorBefore?.林茜?.堕落 ?? before.林茜.堕落);
  const previousFacts = Array.isArray(priorFacts) ? priorFacts : [];
  if (Number.isFinite(floorAffection)) {
    const current = relationshipTotals([...previousFacts, facts]);
    result.林茜.感情 = Math.min(
      999,
      Math.max(0, floorAffection + current.daily + current.intimacy),
    );
  }
  if (!Number.isFinite(floorCorruption)) return;
  result.林茜.堕落 = Math.min(
    999,
    Math.max(0, floorCorruption + corruptionTotal([...previousFacts, facts])),
  );
}

function deriveEnding(before, result, facts) {
  if (!before?.世界 || !result?.世界) return;
  const world = result.世界;
  const prior = before.世界;
  world.终局路线 = prior.终局路线;
  world.终局阶段 = prior.终局阶段;
  world.已离婚 = prior.已离婚;
  world.开局模式 = prior.开局模式;

  const ending = facts?.ending;
  if (ending?.routeRulesLoaded === true && ending.formedRoute) {
    if (
      prior.终局路线 === routeValues.unassigned ||
      ending.explicitReselection === true
    )
      world.终局路线 = ending.formedRoute;
  }
  if (ending?.routeRulesLoaded === true && ending.divorceFormed === true)
    world.已离婚 = true;

  const completed = ending?.completedStage;
  if (completed === constants.sharedEndingStage) {
    if (prior.终局路线 === routeValues.divorce) world.终局阶段 = "Z010";
    if (prior.终局路线 === routeValues.mutualInfidelity)
      world.终局阶段 = "Z013";
  } else if (
    typeof completed === "string" &&
    /^Z00[1-9]$|^Z01[0-3]$/.test(completed)
  ) {
    world.终局阶段 = completed;
  }
}

export function derive({ before, candidate, facts, priorFacts, floorBefore }) {
  const result = clone(candidate);
  if (result?.林茜) {
    coerceFinite(result.林茜, "感情", 0, 999);
    coerceFinite(result.林茜, "堕落", 0, 999);
  }
  if (result?.世界) {
    coerceFinite(result.世界, "小时", 0, 23, true);
    coerceFinite(result.世界, "分钟", 0, 59, true);
    coerceFinite(result.世界, "状态_A1_计数", 0, 9);
  }
  deriveClock(before, result, facts);
  if (
    result?.世界 &&
    typeof facts?.finalLocation === "string" &&
    facts.finalLocation.trim()
  ) {
    result.世界.地点 = facts.finalLocation.trim();
  }
  deriveA1(before, result, facts);
  if (facts?.d001Completed === true && result?.世界)
    result.世界.事件_D001记录日期 = result.世界.日期;
  deriveEvents(before, result, facts);
  deriveNumbers(before, result, facts, priorFacts, floorBefore);
  deriveEnding(before, result, facts);
  return result;
}

export function mount({ api }) {
  const config = api.data.get("ui");
  const status = api.ui.register("status", {
    elements: {
      title: { selector: "#status-title", kind: "text" },
      place: { selector: "#status-place", kind: "text" },
      date: { selector: "#status-date", kind: "text" },
      time: { selector: "#status-time", kind: "text" },
      affection: { selector: "#status-affection", kind: "text" },
      fall: { selector: "#status-fall", kind: "text" },
      affectionBar: { selector: "#status-affection-bar", kind: "progress" },
      fallBar: { selector: "#status-fall-bar", kind: "progress" },
      thought: { selector: "#status-thought", kind: "text" },
    },
  });
  status.update({ title: { text: config.labels.status } });
  const pad = (value) => String(value).padStart(2, "0");
  const displayValue = (value) => {
    if (typeof value === "string" && value.trim()) return value;
    if (typeof value === "number" && Number.isFinite(value)) return String(value);
    return config.labels.unavailable;
  };
  status.bind("view", ({ variables }) => {
    const world = variables?.世界;
    const person = variables?.林茜;
    const dateMatch = typeof world?.日期 === "string"
      ? world.日期.match(/^(\d{4})-(\d{2})-(\d{2})$/)
      : null;
    const dateText = dateMatch && typeof world?.星期 === "string"
      ? `${dateMatch[1]}年${dateMatch[2]}月${dateMatch[3]}日 ${world.星期}`
      : config.labels.unavailable;
    const hour = Number.isInteger(world?.小时) && world.小时 >= 0 && world.小时 <= 23
      ? world.小时
      : null;
    const minute = Number.isInteger(world?.分钟) && world.分钟 >= 0 && world.分钟 <= 59
      ? world.分钟
      : null;
    const timeText = hour !== null && minute !== null && typeof world?.时间 === "string"
      ? `${pad(hour)}:${pad(minute)} · ${world.时间}`
      : config.labels.unavailable;
    const affection = typeof person?.感情 === "number" && Number.isFinite(person.感情)
      ? Math.max(0, Math.min(999, person.感情))
      : 0;
    const fall = typeof person?.堕落 === "number" && Number.isFinite(person.堕落)
      ? Math.max(0, Math.min(999, person.堕落))
      : 0;
    return {
      place: { text: displayValue(world?.地点) },
      date: { text: dateText },
      time: { text: timeText },
      affection: { text: displayValue(typeof person?.感情 === "number" ? Math.round(person.感情) : null) },
      fall: { text: displayValue(typeof person?.堕落 === "number" ? Math.round(person.堕落) : null) },
      affectionBar: { value: affection, min: 0, max: 999 },
      fallBar: { value: fall, min: 0, max: 999 },
      thought: { text: typeof person?.内心想法 === "string"
        ? person.内心想法.replace(/^\*\*/, "").replace(/\*\*$/, "")
        : config.labels.unavailable },
    };
  });

  const elements = {
    actionsTitle: { selector: "#actions-title", kind: "text" },
    chat: { selector: "#chat", kind: "container" },
    feedback: { selector: "#action-feedback", kind: "text" },
    repairTitle: { selector: "#repair-title", kind: "text" },
    recalculate: { selector: "#repair-recalculate", kind: "control" },
    recalculateText: { selector: "#repair-recalculate-text", kind: "text" },
    restore: { selector: "#repair-restore", kind: "control" },
    restoreText: { selector: "#repair-restore-text", kind: "text" },
    repairFeedback: { selector: "#repair-feedback", kind: "text" },
  };
  for (let index = 0; index < config.optionCount; index += 1) {
    elements[`option${index}`] = { selector: `#option-${index}`, kind: "control" };
    elements[`text${index}`] = { selector: `#option-text-${index}`, kind: "text" };
  }
  const controls = api.ui.register("actions", { elements });
  controls.update({
    actionsTitle: { text: config.labels.actions },
    repairTitle: { text: config.labels.repair },
    recalculateText: { text: config.labels.recalculate },
    restoreText: { text: config.labels.restore },
  });

  let choices = [];
  let busy = false;
  const validChoices = (values) =>
    Array.isArray(values) &&
    values.length === config.optionCount &&
    new Set(values.map((value) => typeof value === "string" ? value.trim() : "")).size === config.optionCount &&
    values.every((value, index) =>
      typeof value === "string" &&
      value.trim().length > 0 &&
      (index !== 0 && index !== config.optionCount - 1 || value.startsWith(config.directivePrefix))
    );
  const refresh = () => {
    const ready = validChoices(choices);
    const patch = {};
    for (let index = 0; index < config.optionCount; index += 1) {
      patch[`text${index}`] = { text: ready ? choices[index] : "" };
      patch[`option${index}`] = { disabled: busy || !ready };
    }
    controls.update(patch);
  };
  api.variables.watch("current", ({ variables }) => {
    choices = variables?.行动选项;
    refresh();
  });
  controls.on("recalculate", "click", async () => {
    if (busy) return;
    const current = api.variables.get("current");
    if (!current || current.floorId === null) {
      controls.update({ repairFeedback: { text: config.labels.noFloor } });
      return;
    }
    busy = true;
    refresh();
    controls.update({
      recalculate: { disabled: true },
      restore: { disabled: true },
      repairFeedback: { text: config.labels.working },
    });
    try {
      await api.variables.recalculateLatest({
        branchId: current.branchId,
        floorId: current.floorId,
        expectedSnapshotId: current.snapshotId,
      });
      controls.update({ repairFeedback: { text: config.labels.recalculateDone } });
    } catch (error) {
      controls.update({ repairFeedback: { text: error?.message || config.labels.sendFailed } });
    } finally {
      busy = false;
      refresh();
      controls.update({ recalculate: { disabled: false }, restore: { disabled: false } });
    }
  });
  controls.on("restore", "click", async () => {
    if (busy) return;
    const current = api.variables.get("current");
    if (!current) {
      controls.update({ repairFeedback: { text: config.labels.sendFailed } });
      return;
    }
    busy = true;
    refresh();
    controls.update({
      recalculate: { disabled: true },
      restore: { disabled: true },
      repairFeedback: { text: config.labels.working },
    });
    try {
      const result = await api.variables.restoreMissing({
        branchId: current.branchId,
        expectedSnapshotId: current.snapshotId,
      });
      controls.update({ repairFeedback: {
        text: result.before.snapshotId === result.after.snapshotId
          ? config.labels.restoreNoChange
          : config.labels.restoreDone,
      } });
    } catch (error) {
      controls.update({ repairFeedback: { text: error?.message || config.labels.sendFailed } });
    } finally {
      busy = false;
      refresh();
      controls.update({ recalculate: { disabled: false }, restore: { disabled: false } });
    }
  });
  for (let index = 0; index < config.optionCount; index += 1) {
    controls.on(`option${index}`, "click", async () => {
      if (busy || !validChoices(choices)) return;
      busy = true;
      refresh();
      controls.update({ recalculate: { disabled: true }, restore: { disabled: true } });
      controls.update({ feedback: { text: "" } });
      try {
        await api.chat.send({ text: choices[index] });
      } catch (error) {
        const message = error && typeof error.message === "string"
          ? error.message
          : config.labels.sendFailed;
        controls.update({ feedback: { text: message } });
      } finally {
        busy = false;
        refresh();
        controls.update({ recalculate: { disabled: false }, restore: { disabled: false } });
      }
    });
  }
  api.widgets.mountChat(controls, "chat");
}

{
  "apiVersion": 1,
  "html": "frontend/index.html",
  "css": "frontend/style.css",
  "script": "frontend/main.js",
  "assets": {},
  "data": {
    "ui": "data/role-ui.json"
  }
}

:host {
  --ink: #25211f;
  --ink-soft: #69605a;
  --paper: #fbf8f2;
  --paper-deep: #f0e8dc;
  --line: #dfd2c3;
  --accent: #9b513d;
  --accent-dark: #713a2d;
  --gold: #ba945c;
  display: block;
  color: var(--ink);
  font-family: "PingFang SC", "Microsoft YaHei", sans-serif;
}
* { box-sizing: border-box; }
button { font: inherit; }
.linxi-app {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(270px, 330px);
  align-items: start;
  gap: 18px;
  max-width: 1240px;
  margin: 0 auto;
  padding: 16px;
}
.linxi-chat, .linxi-panel {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--paper);
  box-shadow: 0 8px 24px rgb(48 34 24 / 8%);
}
.linxi-chat { min-width: 0; overflow: hidden; }
.linxi-chat__header {
  padding: 18px 20px 14px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(120deg, #f5eadb, #fcf8f1);
}
.linxi-chat__eyebrow, .linxi-panel__eyebrow {
  margin: 0 0 5px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .12em;
}
.linxi-chat h1 { margin: 0; font-size: 20px; line-height: 1.3; }
.linxi-chat__body { min-height: 450px; }
.linxi-sidebar { display: grid; gap: 14px; }
.linxi-panel { padding: 16px; }
.linxi-panel__header { display: flex; align-items: center; gap: 12px; }
.linxi-panel__header h2 { margin: 0; font-size: 16px; }
.linxi-panel__header--compact { margin-bottom: 12px; }
.linxi-avatar {
  display: grid;
  flex: 0 0 46px;
  width: 46px;
  height: 46px;
  place-items: center;
  border: 1px solid #d7b6a0;
  border-radius: 50%;
  background: #f1dfcf;
  color: var(--accent-dark);
  font-family: serif;
  font-size: 20px;
}
.linxi-place {
  margin: 14px 0 12px;
  padding: 9px 11px;
  border-left: 3px solid var(--accent);
  background: var(--paper-deep);
  color: var(--ink-soft);
  font-size: 13px;
  line-height: 1.5;
}
.linxi-status-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  margin: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--line);
}
.linxi-status-grid > div { min-width: 0; padding: 10px; background: #fffdf9; }
.linxi-status-grid dt { margin-bottom: 4px; color: var(--ink-soft); font-size: 11px; }
.linxi-status-grid dd { min-height: 20px; margin: 0; font-size: 13px; font-weight: 700; overflow-wrap: anywhere; }
progress { display: block; width: 100%; height: 5px; margin-top: 7px; accent-color: var(--accent); }
.linxi-thought { margin-top: 12px; }
.linxi-thought h3 { margin: 0 0 6px; color: var(--ink-soft); font-size: 11px; font-weight: 600; }
.linxi-thought p { margin: 0; max-height: 140px; overflow: auto; color: var(--ink); font-size: 12px; line-height: 1.55; white-space: pre-wrap; overflow-wrap: anywhere; }
.linxi-actions__list { display: grid; gap: 8px; }
.linxi-actions__list button {
  width: 100%;
  min-height: 42px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fffdf9;
  color: var(--ink);
  line-height: 1.5;
  text-align: left;
  overflow-wrap: anywhere;
  cursor: pointer;
}
.linxi-actions__list button:hover:not(:disabled) { border-color: var(--gold); background: #f7eee2; }
.linxi-actions__list button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.linxi-actions__list button:disabled { cursor: not-allowed; opacity: .55; }
.linxi-feedback { min-height: 1.4em; margin: 9px 0 0; color: var(--accent-dark); font-size: 12px; }
@media (max-width: 760px) {
  .linxi-app { grid-template-columns: minmax(0, 1fr); padding: 8px; gap: 10px; }
  .linxi-sidebar { grid-row: 1; }
  .linxi-chat__body { min-height: 340px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; }
}

.linxi-repair { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--line); }
.linxi-repair h3 { margin: 0 0 8px; color: var(--ink-soft); font-size: 12px; font-weight: 600; }
.linxi-repair__actions { display: flex; flex-wrap: wrap; gap: 8px; }
.linxi-repair__actions button { border: 1px solid var(--line); border-radius: 7px; padding: 7px 9px; background: var(--paper-deep); color: var(--ink); font-size: 11px; cursor: pointer; }
.linxi-repair__actions button:hover:not(:disabled) { border-color: var(--gold); }
.linxi-repair__actions button:disabled { cursor: not-allowed; opacity: .55; }

